"""Small immutable audit-head archive, isolated from scientific worker roles."""
import json
def template(account,kms,app_role):
    ref=lambda n:{'Ref':n};att=lambda n,k:{'Fn::GetAtt':[n,k]};tags=[{'Key':'Project','Value':'OpenNGS'}]
    resources={'Archive':{'Type':'AWS::S3::Bucket','DeletionPolicy':'Retain','UpdateReplacePolicy':'Retain','Properties':{'BucketName':'openngs-audit-'+account+'-us-east-1','ObjectLockEnabled':True,'ObjectLockConfiguration':{'ObjectLockEnabled':'Enabled','Rule':{'DefaultRetention':{'Mode':'GOVERNANCE','Days':30}}},'VersioningConfiguration':{'Status':'Enabled'},'BucketEncryption':{'ServerSideEncryptionConfiguration':[{'ServerSideEncryptionByDefault':{'SSEAlgorithm':'aws:kms','KMSMasterKeyID':kms},'BucketKeyEnabled':True}]},'PublicAccessBlockConfiguration':{'BlockPublicAcls':True,'IgnorePublicAcls':True,'BlockPublicPolicy':True,'RestrictPublicBuckets':True},'Tags':tags}},'NoPlaintext':{'Type':'AWS::S3::BucketPolicy','Properties':{'Bucket':ref('Archive'),'PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Deny','Principal':'*','Action':'s3:*','Resource':[att('Archive','Arn'),{'Fn::Sub':'${Archive.Arn}/*'}],'Condition':{'Bool':{'aws:SecureTransport':'false'}}}]}}},'Producer':{'Type':'AWS::IAM::Policy','Properties':{'PolicyName':'OpenNGSImmutableAuditHeads','Roles':[app_role],'PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Action':['s3:PutObject','s3:GetObject','s3:GetObjectVersion','s3:GetObjectRetention'],'Resource':{'Fn::Sub':'${Archive.Arn}/anchors/*'}},{'Effect':'Allow','Action':['s3:ListBucket','s3:ListBucketVersions'],'Resource':att('Archive','Arn')}]}}}}
    trail_arn=f'arn:aws:cloudtrail:us-east-1:{account}:trail/openngs-data-access'
    bucket_arn=f'arn:aws:s3:::openngs-audit-{account}-us-east-1'
    resources['TrailKey']={'Type':'AWS::KMS::Key','DeletionPolicy':'Retain','UpdateReplacePolicy':'Retain','Properties':{'EnableKeyRotation':True,'Description':'Only OpenNGS CloudTrail object-access logs','Tags':tags,'KeyPolicy':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Principal':{'AWS':f'arn:aws:iam::{account}:root'},'Action':'kms:*','Resource':'*'},{'Effect':'Allow','Principal':{'Service':'cloudtrail.amazonaws.com'},'Action':['kms:GenerateDataKey*','kms:Decrypt'],'Resource':'*','Condition':{'StringEquals':{'aws:SourceArn':trail_arn},'StringLike':{'kms:EncryptionContext:aws:cloudtrail:arn':trail_arn}}},{'Effect':'Allow','Principal':{'Service':'cloudtrail.amazonaws.com'},'Action':'kms:DescribeKey','Resource':'*'}]}}}
    statements=resources['NoPlaintext']['Properties']['PolicyDocument']['Statement']
    statements.extend([{'Effect':'Allow','Principal':{'Service':'cloudtrail.amazonaws.com'},'Action':'s3:GetBucketAcl','Resource':bucket_arn,'Condition':{'StringEquals':{'aws:SourceArn':trail_arn}}},{'Effect':'Allow','Principal':{'Service':'cloudtrail.amazonaws.com'},'Action':'s3:PutObject','Resource':bucket_arn+'/cloudtrail/AWSLogs/'+account+'/*','Condition':{'StringEquals':{'aws:SourceArn':trail_arn,'s3:x-amz-acl':'bucket-owner-full-control'}}}])
    resources['ObjectAccessTrail']={'Type':'AWS::CloudTrail::Trail','DependsOn':'NoPlaintext','Properties':{'TrailName':'openngs-data-access','S3BucketName':ref('Archive'),'S3KeyPrefix':'cloudtrail','KMSKeyId':att('TrailKey','Arn'),'IsLogging':True,'IsMultiRegionTrail':False,'IncludeGlobalServiceEvents':False,'EnableLogFileValidation':True,'AdvancedEventSelectors':[{'Name':'OpenNGS object access only','FieldSelectors':[{'Field':'eventCategory','Equals':['Data']},{'Field':'resources.type','Equals':['AWS::S3::Object']},{'Field':'resources.ARN','StartsWith':[f'arn:aws:s3:::ngs-studio-cache-{account}-us-east-1/',f'arn:aws:s3:::openngs-pro-{account}-',bucket_arn+'/anchors/']}]}],'Tags':tags}}
    return {'AWSTemplateFormatVersion':'2010-09-09','Description':'OpenNGS encrypted 30-day governance WORM hash checkpoints; application cannot delete or bypass retention','Resources':resources,'Outputs':{'Bucket':{'Value':ref('Archive')}}}

if __name__=='__main__':
    import sys
    print(json.dumps(template(*sys.argv[1:]),indent=2))
